using Amazon.CDK.AWS.EC2;
using Amazon.CDK;
using Constructs;

class CdkTestStack : Stack
{
    public CdkTestStack(Construct scope, string id, StackProps? props=null) : base(scope, id, props)
    {
        var test = new SecurityGroup(this, "test", new SecurityGroupProps {
            Vpc = new Vpc(this, "vpc")
        });
        test.AddIngressRule(Peer.AnyIpv4(), Port.AllTraffic());
        Validations.Of(test).Acknowledge(new Acknowledgment {
            Id = "AwsSolutions-EC23",
            Reason = "This security group is used for internal testing only."
        });
    }
}

