using Amazon.CDK.AWS.IAM;
using Amazon.CDK;
using Constructs;

class CdkTestStack : Stack
{
    public CdkTestStack(Construct scope, string id, StackProps? props=null) : base(scope, id, props)
    {
        var user = new User(this, "rUser");
        user.AddToPolicy(
        new PolicyStatement(new PolicyStatementProps {
            Actions = new [] { "s3:*" },
            Resources = new [] { "*" }
        }));
        // Only acknowledge the s3:* action — Resource::* still triggers
        Validations.Of(user).Acknowledge(new Acknowledgment {
            Id = "AwsSolutions-IAM5[Action::s3:*]",
            Reason = "Need s3:* for cross-account replication."
        });
    }
}

